import sys
from collections import deque

def read_input():
    input = sys.stdin.read().strip().split('\n\n')
    n, m, k = map(int, input[0].split())
    grid = []
    for layer in input[1:]:
        grid.append([list(map(int, row)) for row in layer.split('\n')])
    return n, m, k, grid

def bfs(n, m, k, grid, start):
    visited = [[[False] * k for _ in range(m)] for _ in range(n)]
    queue = deque([start])
    visited[start[0]][start[1]][start[2]] = True
    while queue:
        x, y, z = queue.popleft()
        for dx, dy, dz in [(1, 0, 0), (0, 1, 0), (0, 0, 1)]:
            nx, ny, nz = x + dx, y + dy, z + dz
            if 0 <= nx < n and 0 <= ny < m and 0 <= nz < k and not visited[nx][ny][nz] and grid[nx][ny][nz] == 1:
                visited[nx][ny][nz] = True
                queue.append((nx, ny, nz))
    return visited

def count_critical_cpus(n, m, k, grid):
    original_reachability = [[[[False] * k for _ in range(m)] for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            for l in range(k):
                if grid[i][j][l] == 1:
                    reachability = bfs(n, m, k, grid, (i, j, l))
                    for x in range(n):
                        for y in range(m):
                            for z in range(k):
                                original_reachability[i][j][l][x][y][z] = reachability[x][y][z]

    critical_count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j][l] == 1:
                grid[i][j][l] = 0
                new_reachability = bfs(n, m, k, grid, (i, j))
                for x in range(n):
                    for y in range(m):
                        for z in range(k):
                            if original_reachability[i][j][x][y][z] and not new_reachability[x][y][z]:
                                critical_count += 1
                grid[i][j][l] = 1

    return critical_count

def main():
    n, m, k, grid = read_input()
    result = count_critical_cpus(n, m, k, grid)
    print(result)

main()
